create or replace function public.gateway_json_contains_forbidden_payment_data(p_value jsonb) returns boolean language plpgsql immutable set search_path = public as $$ declare k text; v jsonb; begin if p_value is null then return false; end if; if jsonb_typeof(p_value)='object' then for k,v in select key,value from jsonb_each(p_value) loop if lower(regexp_replace(k,'[^a-z0-9]','','g')) in ('pan','cardnumber','cardnum','cvv','cvc','securitycode','securitynumber','expiration','expiry','expirymonth','expiryyear','trackdata','magstripe') then return true; end if; if public.gateway_json_contains_forbidden_payment_data(v) then return true; end if; end loop; elsif jsonb_typeof(p_value)='array' then for v in select value from jsonb_array_elements(p_value) loop if public.gateway_json_contains_forbidden_payment_data(v) then return true; end if; end loop; end if; return false; end $$; create or replace function public.gateway_routing_graph_validate_target_refs(p_graph jsonb) returns boolean language plpgsql immutable set search_path = public as $$ begin return public.gateway_routing_graph_validator_v4(p_graph); exception when others then return false; end $$; revoke execute on function public.gateway_routing_graph_validate_target_refs(jsonb) from public, anon, authenticated; revoke execute on function public.gateway_json_contains_forbidden_payment_data(jsonb) from public, anon, authenticated; grant execute on function public.gateway_routing_graph_validate_target_refs(jsonb) to service_role; grant execute on function public.gateway_json_contains_forbidden_payment_data(jsonb) to service_role;